const toasts = ref([]);
let seq = 0;
export function useToasts() {
    return toasts;
}
export function showToast(text, type = 'info', duration = 2600) {
    const id = ++seq;
    toasts.value.push({ id, type, text });
    window.setTimeout(() => {
        toasts.value = toasts.value.filter(t => t.id !== id);
    }, duration);
}
